// Source oracle; run inside a disposable task-owned container.
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {readFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import vm from 'node:vm';
const root = fileURLToPath(new URL('../../', import.meta.url));
const require = createRequire(`${root}/package.json`);
const ts = require('typescript');
const source = readFileSync(`${root}/src/utils/observability/telemetry.ts`, 'utf8');
const compiled = ts.transpileModule(source, {compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;
const module = {exports:{}};
new vm.Script(`(function(exports,require,module){${compiled}\n})`).runInThisContext()(module.exports,require,module);
const t = module.exports;
t.telemetryTesting.enable();
const reset = () => t.telemetryTesting.reset();
reset();
for (const n of [-1, 1, 2, 5, 1e13]) t.observe('work!', 'metric?', n, 'ok!', 'abc-1', 19999);
t.recordLog('warn', {function:'task!',step:'step?',status:200,message:'private-message',extra:'private-extra'}, 'abc-1');
let snapshot = t.telemetryTesting.snapshot();
let logs = snapshot.logs.map(({at, ...row}) => row);
const expected = JSON.parse(readFileSync(new URL('./shared_telemetry_parity.json', import.meta.url)));
assert.deepEqual(JSON.parse(JSON.stringify({metrics:snapshot.metrics,logs,dropped:snapshot.dropped})), expected);
reset();
for (const n of t.LATENCY_BOUNDS) t.observe('kind😀', 'x😀', n, 'ok', 'bad space', 10000);
snapshot = t.telemetryTesting.snapshot();
assert.equal(snapshot.metrics[0].kind,'kind__'); assert.equal(snapshot.metrics[0].name,'x__'); assert.equal(snapshot.metrics[0].channel,'');
assert.deepEqual(snapshot.metrics[0].histogram, Array(16).fill(1));
reset();
t.observe('overflow','sum',Number.MAX_VALUE,'ok','',10000); t.observe('overflow','sum',Number.MAX_VALUE,'ok','',10000);
assert.equal(JSON.parse(JSON.stringify(t.telemetryTesting.snapshot().metrics[0])).sum,null);
reset();
for (let i=0; i<2001; i++) t.observe('kind', `key${i}`, 1, 'ok', 'abc', 10000);
t.observe('kind','key0',1,'ok','abc',10000);
assert.equal(t.telemetryTesting.snapshot().metrics.length,2000); assert.equal(t.telemetryTesting.snapshot().dropped,1); assert.equal(t.telemetryTesting.snapshot().metrics[0].count,2);
reset();
for (const level of ['trace','debug','info','warn','error','fatal']) t.recordLog(level,{function:42,operation:'fallback',message:'secret',attempt:2},'bad space');
snapshot = t.telemetryTesting.snapshot(); assert.equal(snapshot.logs.length,3); assert.equal(snapshot.logs[0].name,'42'); assert.equal(snapshot.logs[0].channel,''); assert.deepEqual(snapshot.logs[0].fields,{function:42,operation:'fallback',attempt:2});
for (let i=0;i<100;i++) t.recordLog('warn',{},''); assert.equal(t.telemetryTesting.snapshot().dropped,3);
reset();
t.restoreContext({traceId:'a'.repeat(32),spanId:'b'.repeat(16),sampled:true},'chan',()=>{const span=t.beginSpan('work','start'); span.run(()=>t.traceOutcome('')); span.end('ok',''); span.end('error');});
snapshot=t.telemetryTesting.snapshot(); assert.equal(snapshot.spans.length,1); assert.equal(snapshot.spans[0].outcome,'ok'); assert.equal(snapshot.spans[0].name,'start');
reset();
t.restoreContext({traceId:'a'.repeat(32),spanId:'b'.repeat(16),sampled:true},'tenant',()=>{for(const ch of [undefined,'bad space','','other']) t.recordLog('warn',{function:'operation'},ch);});
assert.deepEqual(t.telemetryTesting.snapshot().logs.map(row=>row.channel),['tenant','','','other']);
t.telemetryTesting.stop();
console.log('shared telemetry source parity checks passed');
